import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport
} from './index.js';
import { toMarkdown } from './reporters.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('adds threshold results to report when thresholds are provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.5,
        toxicity: 0.8
      }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toEqual([
      { metric: 'exact_match', min: 0.5, score: expect.any(Number), passed: true },
      { metric: 'toxicity', min: 0.8, score: expect.any(Number), passed: true }
    ]);
  });

  it('marks report as failed when any threshold fails', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9
      }
    });

    expect(report.passed).toBe(false);
    const exactMatchThreshold = report.thresholds.find((t) => t.metric === 'exact_match');
    expect(exactMatchThreshold.passed).toBe(false);
  });

  it('handles metrics with null scores as failing thresholds', () => {
    const evaluations = [
      {
        id: 'exact_match',
        label: 'Exact Match',
        score: null,
        total: 0
      }
    ];
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: null,
      thresholds: {
        exact_match: 0.5
      }
    });

    expect(report.passed).toBe(false);
    const threshold = report.thresholds.find((t) => t.metric === 'exact_match');
    expect(threshold.passed).toBe(false);
    expect(threshold.score).toBe(null);
  });

  it('does not include thresholds in report when none are provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });

  it('includes threshold results in markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.5,
        toxicity: 0.8
      }
    });

    const markdown = (require('./reporters.js') as any).toMarkdown(report);
    expect(markdown).toContain('## Thresholds');
    expect(markdown).toContain('exact_match');
    expect(markdown).toContain('toxicity');
    expect(markdown).toContain('PASS');
  });

  it('shows FAIL status in markdown when threshold fails', () => {
    const evaluations = [
      {
        id: 'exact_match',
        label: 'Exact Match',
        score: 0.5,
        total: 2,
        matches: 1
      }
    ];
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9
      }
    });

    const markdown = (require('./reporters.js') as any).toMarkdown(report);
    expect(markdown).toContain('exact_match');
    expect(markdown).toContain('FAIL');
    expect(markdown).toContain('min: 0.9');
    expect(markdown).toContain('score: 0.5');
  });
});

